### 5. `services.tf`

```hcl
# ------------------------------------------------------------------------------
# 1. Enable Required GCP APIs
# ------------------------------------------------------------------------------
locals {
  required_services = [
    "compute.googleapis.com",
    "servicenetworking.googleapis.com",
    "vpcaccess.googleapis.com",
    "run.googleapis.com",
    "sqladmin.googleapis.com",
    "storage.googleapis.com",
    "cloudkms.googleapis.com",
    "secretmanager.googleapis.com",
    "logging.googleapis.com",
    "monitoring.googleapis.com"
  ]
}

resource "google_project_service" "apis" {
  for_each                   = toset(locals.required_services)
  project                    = var.project_id
  service                    = each.key
  disable_on_destroy         = false
  disable_dependent_services = false
}

# ------------------------------------------------------------------------------
# 2. Hardened Cloud Storage Bucket (CMEK Encrypted)
# ------------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "google_storage_bucket" "media_assets" {
  name                        = "ecommerce-${var.environment}-media-${var.region}-${random_id.bucket_suffix.hex}"
  location                    = var.region
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  versioning {
    enabled = true
  }

  encryption {
    default_kms_key_name = google_kms_crypto_key.storage_key.id
  }

  lifecycle_rule {
    action {
      type          = "SetStorageClass"
      storage_class = "NEARLINE"
    }
    condition {
      age = 90
    }
  }

  lifecycle_rule {
    action {
      type          = "SetStorageClass"
      storage_class = "COLDLINE"
    }
    condition {
      age = 365
    }
  }

  depends_on = [
    google_kms_crypto_key_iam_member.storage_sa_kms,
    google_project_service.apis
  ]
}

# IAM Object User Binding for Backend API SA
resource "google_storage_bucket_iam_member" "backend_storage_access" {
  bucket = google_storage_bucket.media_assets.name
  role   = "roles/storage.objectUser"
  member = "serviceAccount:${google_service_account.sa_cloudrun_backend.email}"
}

# Conditional Object Viewer Binding for Frontend SA
resource "google_storage_bucket_iam_member" "frontend_storage_access" {
  bucket = google_storage_bucket.media_assets.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.sa_cloudrun_frontend.email}"

  condition {
    title       = "allow_public_media_path"
    description = "Restricts frontend SA to reading objects under public/ prefix"
    expression  = "resource.name.startsWith(\"projects/_/buckets/${google_storage_bucket.media_assets.name}/objects/public/\")"
  }
}

# ------------------------------------------------------------------------------
# 3. Secret Manager for Database Credentials (CMEK Encrypted)
# ------------------------------------------------------------------------------
resource "random_password" "db_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "google_secret_manager_secret" "db_credentials" {
  secret_id = "db-ecommerce-credentials"

  customer_managed_encryption {
    kms_key_name = google_kms_crypto_key.secrets_key.id
  }

  replication {
    user_managed {
      replicas {
        location = var.region
      }
    }
  }

  depends_on = [
    google_kms_crypto_key_iam_member.secrets_sa_kms,
    google_project_service.apis
  ]
}

resource "google_secret_manager_secret_version" "db_credentials_version" {
  secret      = google_secret_manager_secret.db_credentials.id
  secret_data = jsonencode({
    username = "ecommerce_admin"
    password = random_password.db_password.result
    database = "ecommerce_db"
  })
}

resource "google_secret_manager_secret_iam_member" "backend_secret_access" {
  secret_id = google_secret_manager_secret.db_credentials.id
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${google_service_account.sa_cloudrun_backend.email}"
}

resource "google_secret_manager_secret_iam_member" "ops_secret_access" {
  secret_id = google_secret_manager_secret.db_credentials.id
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${google_service_account.sa_cloudsql_ops.email}"
}

# ------------------------------------------------------------------------------
# 4. Regional High Availability Cloud SQL for PostgreSQL 15 (Private IP & CMEK)
# ------------------------------------------------------------------------------
resource "random_id" "db_name_suffix" {
  byte_length = 3
}

resource "google_sql_database_instance" "postgres_ha" {
  name                = "pg-ecommerce-prod-${random_id.db_name_suffix.hex}"
  database_version    = "POSTGRES_15"
  region              = var.region
  deletion_protection = true
  encryption_key_name = google_kms_crypto_key.sql_key.id

  settings {
    tier              = var.cloud_sql_tier
    availability_type = "REGIONAL"
    disk_type         = "PD_SSD"
    disk_size         = 50
    disk_autoresize   = true
    disk_autoresize_limit = 500

    ip_configuration {
      ipv4_enabled                                  = false
      private_network                               = google_compute_network.vpc.id
      enable_private_path_for_google_cloud_services = true
      ssl_mode                                      = "VERIFY_X509"
    }

    backup_configuration {
      enabled                        = true
      start_time                     = "03:00"
      point_in_time_recovery_enabled = true
      transaction_log_retention_days = 7
      backup_retention_settings {
        retained_backups = 7
        retention_unit   = "COUNT"
      }
    }

    maintenance_window {
      day          = 7 # Sunday
      hour         = 4 # 04:00 AM UTC
      update_track = "stable"
    }

    database_flags {
      name  = "log_connections"
      value = "on"
    }
    database_flags {
      name  = "log_disconnections"
      value = "on"
    }
    database_flags {
      name  = "log_checkpoints"
      value = "on"
    }
  }

  depends_on = [
    google_service_networking_connection.private_vpc_connection,
    google_kms_crypto_key_iam_member.sql_sa_kms,
    google_project_service.apis
  ]
}

resource "google_sql_database" "ecommerce_db" {
  name     = "ecommerce_db"
  instance = google_sql_database_instance.postgres_ha.name
}

resource "google_sql_user" "ecommerce_admin" {
  name     = "ecommerce_admin"
  instance = google_sql_database_instance.postgres_ha.name
  password = random_password.db_password.result
}
```

