### 6. `compute.tf`

```hcl
# ------------------------------------------------------------------------------
# 1. Serverless VPC Access Connector
# ------------------------------------------------------------------------------
resource "google_vpc_access_connector" "connector" {
  name          = "vpc-connector-ecommerce"
  region        = var.region
  ip_cidr_range = var.subnet_cidr_vpc_connector
  network       = google_compute_network.vpc.name
  min_instances = 2
  max_instances = 10
  machine_type  = "e2-micro"

  depends_on = [
    google_compute_subnetwork.sb_vpc_connector,
    google_project_service.apis
  ]
}

# ------------------------------------------------------------------------------
# 2. Cloud Run Service: Frontend Web Tier
# ------------------------------------------------------------------------------
resource "google_cloud_run_v2_service" "frontend" {
  name     = "cr-ecommerce-frontend"
  location = var.region
  ingress  = "INGRESS_TRAFFIC_INTERNAL_LOAD_BALANCER"

  template {
    service_account                  = google_service_account.sa_cloudrun_frontend.email
    max_instance_request_concurrency = 80

    scaling {
      min_instance_count = 2
      max_instance_count = 20
    }

    vpc_access {
      connector = google_vpc_access_connector.connector.id
      egress    = "ALL_TRAFFIC"
    }

    containers {
      image = var.frontend_container_image

      resources {
        limits = {
          cpu    = "2000m"
          memory = "2Gi"
        }
      }

      ports {
        container_port = 8080
      }

      env {
        name  = "ENVIRONMENT"
        value = var.environment
      }
      env {
        name  = "MEDIA_BUCKET_NAME"
        value = google_storage_bucket.media_assets.name
      }
    }
  }

  depends_on = [
    google_vpc_access_connector.connector,
    google_project_service.apis
  ]
}

# ------------------------------------------------------------------------------
# 3. Cloud Run Service: Backend API Microservices Tier
# ------------------------------------------------------------------------------
resource "google_cloud_run_v2_service" "backend_api" {
  name     = "cr-ecommerce-backend-api"
  location = var.region
  ingress  = "INGRESS_TRAFFIC_INTERNAL_LOAD_BALANCER"

  template {
    service_account                  = google_service_account.sa_cloudrun_backend.email
    max_instance_request_concurrency = 80

    scaling {
      min_instance_count = 2
      max_instance_count = 20
    }

    vpc_access {
      connector = google_vpc_access_connector.connector.id
      egress    = "ALL_TRAFFIC"
    }

    containers {
      image = var.backend_container_image

      resources {
        limits = {
          cpu    = "2000m"
          memory = "4Gi"
        }
      }

      ports {
        container_port = 8080
      }

      env {
        name  = "ENVIRONMENT"
        value = var.environment
      }
      env {
        name  = "DB_HOST"
        value = google_sql_database_instance.postgres_ha.private_ip_address
      }
      env {
        name  = "DB_NAME"
        value = google_sql_database.ecommerce_db.name
      }
      env {
        name  = "DB_SECRET_ID"
        value = google_secret_manager_secret.db_credentials.secret_id
      }
      env {
        name  = "MEDIA_BUCKET_NAME"
        value = google_storage_bucket.media_assets.name
      }
    }
  }

  depends_on = [
    google_vpc_access_connector.connector,
    google_sql_database_instance.postgres_ha,
    google_project_service.apis
  ]
}

# ------------------------------------------------------------------------------
# 4. Service-to-Service Invocation Authorization
# ------------------------------------------------------------------------------
# Frontend SA is permitted to invoke the Backend API
resource "google_cloud_run_v2_service_iam_member" "frontend_invokes_backend" {
  location = google_cloud_run_v2_service.backend_api.location
  name     = google_cloud_run_v2_service.backend_api.name
  role     = "roles/run.invoker"
  member   = "serviceAccount:${google_service_account.sa_cloudrun_frontend.email}"
}

# Load Balancer Proxies require invoker privileges
resource "google_cloud_run_v2_service_iam_member" "lb_invoker_frontend" {
  location = google_cloud_run_v2_service.frontend.location
  name     = google_cloud_run_v2_service.frontend.name
  role     = "roles/run.invoker"
  member   = "allUsers" # Ingress restricted at L7 ALB + Cloud Armor edge
}

resource "google_cloud_run_v2_service_iam_member" "lb_invoker_backend" {
  location = google_cloud_run_v2_service.backend_api.location
  name     = google_cloud_run_v2_service.backend_api.name
  role     = "roles/run.invoker"
  member   = "allUsers" # Ingress restricted at L7 ALB + Cloud Armor edge
}
```

