### 7. `loadbalancer.tf`

```hcl
# ------------------------------------------------------------------------------
# 1. Global Static Anycast IP Address
# ------------------------------------------------------------------------------
resource "google_compute_global_address" "alb_ip" {
  name        = "pip-alb-ecommerce"
  ip_version  = "IPV4"
  description = "Global anycast IPv4 entry point for E-Commerce ALB"
}

# ------------------------------------------------------------------------------
# 2. Strict TLS 1.2+ SSL Policy
# ------------------------------------------------------------------------------
resource "google_compute_ssl_policy" "strict_ssl_policy" {
  name            = "ssl-policy-ecommerce-strict"
  profile         = "RESTRICTED"
  min_tls_version = "TLS_1_2"
}

# ------------------------------------------------------------------------------
# 3. Google-Managed SSL Certificate
# ------------------------------------------------------------------------------
resource "google_compute_managed_ssl_certificate" "alb_cert" {
  name = "cert-ecommerce-prod"

  managed {
    domains = var.domain_names
  }
}

# ------------------------------------------------------------------------------
# 4. Serverless Network Endpoint Groups (Serverless NEGs)
# ------------------------------------------------------------------------------
resource "google_compute_region_network_endpoint_group" "frontend_neg" {
  name                  = "neg-ecommerce-frontend-us-central1"
  network_endpoint_type = "SERVERLESS"
  region                = var.region

  cloud_run {
    service = google_cloud_run_v2_service.frontend.name
  }
}

resource "google_compute_region_network_endpoint_group" "backend_neg" {
  name                  = "neg-ecommerce-api-us-central1"
  network_endpoint_type = "SERVERLESS"
  region                = var.region

  cloud_run {
    service = google_cloud_run_v2_service.backend_api.name
  }
}

# ------------------------------------------------------------------------------
# 5. Backend Services with Attached Cloud Armor WAF
# ------------------------------------------------------------------------------
resource "google_compute_backend_service" "frontend_backend" {
  name                  = "bs-ecommerce-frontend"
  protocol              = "HTTPS"
  load_balancing_scheme = "EXTERNAL_MANAGED"
  security_policy       = google_compute_security_policy.ca_edge_policy.id

  backend {
    group = google_compute_region_network_endpoint_group.frontend_neg.id
  }

  log_config {
    enable      = true
    sample_rate = 1.0
  }
}

resource "google_compute_backend_service" "api_backend" {
  name                  = "bs-ecommerce-api"
  protocol              = "HTTPS"
  load_balancing_scheme = "EXTERNAL_MANAGED"
  security_policy       = google_compute_security_policy.ca_edge_policy.id

  backend {
    group = google_compute_region_network_endpoint_group.backend_neg.id
  }

  log_config {
    enable      = true
    sample_rate = 1.0
  }
}

# ------------------------------------------------------------------------------
# 6. URL Maps & Routing Logic
# ------------------------------------------------------------------------------
resource "google_compute_url_map" "https_url_map" {
  name            = "url-map-ecommerce-https"
  default_service = google_compute_backend_service.frontend_backend.id

  # Host rule 1: shop.ecommerce.domain.com
  host_rule {
    hosts        = ["shop.ecommerce.domain.com"]
    path_matcher = "shop-matcher"
  }

  # Host rule 2: api.ecommerce.domain.com
  host_rule {
    hosts        = ["api.ecommerce.domain.com"]
    path_matcher = "api-direct-matcher"
  }

  path_matcher {
    name            = "shop-matcher"
    default_service = google_compute_backend_service.frontend_backend.id

    path_rule {
      paths   = ["/api/*"]
      service = google_compute_backend_service.api_backend.id
    }
  }

  path_matcher {
    name            = "api-direct-matcher"
    default_service = google_compute_backend_service.api_backend.id
  }
}

# HTTP to HTTPS Redirection URL Map
resource "google_compute_url_map" "http_redirect" {
  name = "url-map-ecommerce-http-redirect"

  default_url_redirect {
    https_redirect         = true
    redirect_response_code = "MOVED_PERMANENTLY_DEFAULT"
    strip_query            = false
  }
}

# ------------------------------------------------------------------------------
# 7. Target Proxies
# ------------------------------------------------------------------------------
resource "google_compute_target_https_proxy" "https_proxy" {
  name             = "tp-ecommerce-prod-https"
  url_map          = google_compute_url_map.https_url_map.id
  ssl_certificates = [google_compute_managed_ssl_certificate.alb_cert.id]
  ssl_policy       = google_compute_ssl_policy.strict_ssl_policy.id
}

resource "google_compute_target_http_proxy" "http_proxy" {
  name    = "tp-ecommerce-prod-http"
  url_map = google_compute_url_map.http_redirect.id
}

# ------------------------------------------------------------------------------
# 8. Global Forwarding Rules (Port 443 & Port 80)
# ------------------------------------------------------------------------------
resource "google_compute_global_forwarding_rule" "https_forwarding_rule" {
  name                  = "fw-rule-ecommerce-global-https"
  target                = google_compute_target_https_proxy.https_proxy.id
  port_range            = "443"
  ip_protocol           = "TCP"
  ip_address            = google_compute_global_address.alb_ip.address
  load_balancing_scheme = "EXTERNAL_MANAGED"
}

resource "google_compute_global_forwarding_rule" "http_forwarding_rule" {
  name                  = "fw-rule-ecommerce-global-http"
  target                = google_compute_target_http_proxy.http_proxy.id
  port_range            = "80"
  ip_protocol           = "TCP"
  ip_address            = google_compute_global_address.alb_ip.address
  load_balancing_scheme = "EXTERNAL_MANAGED"
}
