### 3. `network.tf`

```hcl
# ------------------------------------------------------------------------------
# 1. Custom VPC Network
# ------------------------------------------------------------------------------
resource "google_compute_network" "vpc" {
  name                            = var.vpc_name
  auto_create_subnetworks         = false
  routing_mode                    = "REGIONAL"
  mtu                             = 1460
  delete_default_routes_on_create = false
}

# ------------------------------------------------------------------------------
# 2. Subnets
# ------------------------------------------------------------------------------

# Serverless VPC Access Subnet
resource "google_compute_subnetwork" "sb_vpc_connector" {
  name                     = "sb-ecommerce-vpc-connector"
  ip_cidr_range            = var.subnet_cidr_vpc_connector
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = false
}

# Private Application Subnet
resource "google_compute_subnetwork" "sb_apps" {
  name                     = "sb-ecommerce-apps-us-central1"
  ip_cidr_range            = var.subnet_cidr_apps
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}

# Private Auxiliary / Database Ops Subnet
resource "google_compute_subnetwork" "sb_db_aux" {
  name                     = "sb-ecommerce-db-backup-aux"
  ip_cidr_range            = var.subnet_cidr_db_aux
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}

# Private Service Connect Endpoints Subnet
resource "google_compute_subnetwork" "sb_psc_endpoints" {
  name                     = "sb-ecommerce-psc-endpoints"
  ip_cidr_range            = var.subnet_cidr_psc_endpoints
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}

# Regional Proxy-Only Subnet (for Envoy fallback / internal L7 load balancers)
resource "google_compute_subnetwork" "sb_proxy_only" {
  name          = "sb-ecommerce-proxy-only"
  ip_cidr_range = var.subnet_cidr_proxy_only
  region        = var.region
  network       = google_compute_network.vpc.id
  purpose       = "REGIONAL_MANAGED_PROXY"
  role          = "ACTIVE"
}

# ------------------------------------------------------------------------------
# 3. Private Services Access (PSA) for Cloud SQL
# ------------------------------------------------------------------------------
resource "google_compute_global_address" "psa_reserved_range" {
  name          = "sn-cloud-sql-psa-reserved"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.vpc.id
  address       = split("/", var.psa_reserved_peering_range)[0]
}

resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.vpc.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.psa_reserved_range.name]
}

# ------------------------------------------------------------------------------
# 4. Cloud Router & Cloud NAT for Secure Egress
# ------------------------------------------------------------------------------
resource "google_compute_router" "router" {
  name    = "cr-ecommerce-us-central1"
  region  = var.region
  network = google_compute_network.vpc.name

  bgp {
    asn               = 64514
    keepalive_interval = 20
  }
}

resource "google_compute_address" "nat_ip_1" {
  name   = "pip-nat-ecommerce-01"
  region = var.region
}

resource "google_compute_address" "nat_ip_2" {
  name   = "pip-nat-ecommerce-02"
  region = var.region
}

resource "google_compute_router_nat" "nat" {
  name                               = "nat-ecommerce-us-central1"
  router                             = google_compute_router.router.name
  region                             = var.region
  nat_ip_allocate_option             = "MANUAL_ONLY"
  nat_ips                            = [google_compute_address.nat_ip_1.self_link, google_compute_address.nat_ip_2.self_link]
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"

  min_ports_per_vm                 = 64
  max_ports_per_vm                 = 1024
  enable_dynamic_port_allocation   = true

  tcp_established_idle_timeout_sec = 1200
  tcp_transitory_idle_timeout_sec  = 30
  udp_idle_timeout_sec             = 30
  icmp_idle_timeout_sec            = 30

  log_config {
    enable = true
    filter = "ERRORS_AND_WARNINGS"
  }
}

# ------------------------------------------------------------------------------
# 5. Least-Privilege Firewall Rules
# ------------------------------------------------------------------------------

# Baseline Ingress Lockdown
resource "google_compute_firewall" "deny_all_ingress" {
  name      = "fw-deny-all-ingress"
  network   = google_compute_network.vpc.name
  direction = "INGRESS"
  priority  = 65534

  deny {
    protocol = "all"
  }

  source_ranges = ["0.0.0.0/0"]
}

# Allow Google Cloud Health Checks
resource "google_compute_firewall" "allow_health_checks" {
  name      = "fw-allow-health-checks"
  network   = google_compute_network.vpc.name
  direction = "INGRESS"
  priority  = 1000

  allow {
    protocol = "tcp"
    ports    = ["80", "443", "8080"]
  }

  source_ranges = ["35.191.0.0/16", "130.211.0.0/22"]
  target_tags   = ["load-balanced-backend", "proxy-backend"]
}

# Allow Serverless VPC Connector Inbound into Compute/Database Instances
resource "google_compute_firewall" "allow_vpc_connector_inbound" {
  name      = "fw-allow-vpc-connector-inbound"
  network   = google_compute_network.vpc.name
  direction = "INGRESS"
  priority  = 1005

  allow {
    protocol = "tcp"
    ports    = ["5432", "8080"]
  }

  source_ranges = [var.subnet_cidr_vpc_connector]
  target_tags   = ["db-client", "app-backend"]
}

# Allow Internal Mesh Communication
resource "google_compute_firewall" "allow_internal_mesh" {
  name      = "fw-allow-internal-mesh"
  network   = google_compute_network.vpc.name
  direction = "INGRESS"
  priority  = 1010

  allow {
    protocol = "tcp"
    ports    = ["8080", "8443"]
  }

  source_ranges = ["10.10.0.0/16"]
  target_tags   = ["internal-workload"]
}

# Allow IAP Tunnel for Bastion/Ops Administration
resource "google_compute_firewall" "allow_iap_ssh" {
  name      = "fw-allow-iap-ssh-tunnel"
  network   = google_compute_network.vpc.name
  direction = "INGRESS"
  priority  = 1020

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["35.235.240.0/20"]
  target_tags   = ["iap-bastion"]
}

# Baseline Egress Lockdown
resource "google_compute_firewall" "deny_all_egress" {
  name      = "fw-deny-all-egress"
  network   = google_compute_network.vpc.name
  direction = "EGRESS"
  priority  = 65534

  deny {
    protocol = "all"
  }

  destination_ranges = ["0.0.0.0/0"]
}

# Egress to Cloud SQL Private Services Access
resource "google_compute_firewall" "allow_egress_psa_sql" {
  name      = "fw-allow-egress-to-psa-sql"
  network   = google_compute_network.vpc.name
  direction = "EGRESS"
  priority  = 1000

  allow {
    protocol = "tcp"
    ports    = ["5432"]
  }

  destination_ranges = [var.psa_reserved_peering_range]
  target_tags        = ["db-client", "vpc-connector"]
}

# Egress to Google APIs via Private Google Access & PSC
resource "google_compute_firewall" "allow_egress_google_apis" {
  name      = "fw-allow-egress-to-google-apis"
  network   = google_compute_network.vpc.name
  direction = "EGRESS"
  priority  = 1005

  allow {
    protocol = "tcp"
    ports    = ["443"]
  }

  destination_ranges = ["199.36.153.8/30", var.subnet_cidr_psc_endpoints]
}

# Egress via NAT Gateway for External Web APIs
resource "google_compute_firewall" "allow_egress_nat_web" {
  name      = "fw-allow-egress-nat-web"
  network   = google_compute_network.vpc.name
  direction = "EGRESS"
  priority  = 1010

  allow {
    protocol = "tcp"
    ports    = ["80", "443"]
  }

  destination_ranges = ["0.0.0.0/0"]
  target_tags        = ["egress-nat-enabled"]
}

# Egress for Internal and Metadata DNS Resolution
resource "google_compute_firewall" "allow_egress_dns" {
  name      = "fw-allow-egress-dns"
  network   = google_compute_network.vpc.name
  direction = "EGRESS"
  priority  = 1015

  allow {
    protocol = "tcp"
    ports    = ["53"]
  }

  allow {
    protocol = "udp"
    ports    = ["53"]
  }

  destination_ranges = ["169.254.169.254/32", "10.10.4.10/32"]
}
