  value       = google_kms_key_ring.ecommerce_keyring.name
}

output "cloud_sql_instance_name" {
  description = "The name of the Cloud SQL PostgreSQL 15 Regional HA instance."
  value       = google_sql_database_instance.postgres_ha.name
}

output "cloud_sql_private_ip" {
  description = "The RFC 1918 private IP address allocated to the Cloud SQL PostgreSQL HA cluster."
  value       = google_sql_database_instance.postgres_ha.private_ip_address
}

output "gcs_media_bucket_name" {
  description = "The name of the CMEK-encrypted Cloud Storage media bucket."
  value       = google_storage_bucket.media_assets.name
}

output "frontend_cloud_run_uri" {
  description = "The direct internal URI of the frontend Cloud Run microservice."
  value       = google_cloud_run_v2_service.frontend.uri
}

output "backend_cloud_run_uri" {
  description = "The direct internal URI of the backend API Cloud Run microservice."
  value       = google_cloud_run_v2_service.backend_api.uri
}

output "service_account_frontend_email" {
  description = "The service account email executing the frontend microservice."
  value       = google_service_account.sa_cloudrun_frontend.email
}

output "service_account_backend_email" {
  description = "The service account email executing the backend microservice."
  value       = google_service_account.sa_cloudrun_backend.email
}
