```hcl
# Random ID suffix to ensure globally unique names for Cloud Storage buckets
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# 1. Cloud Storage Buckets (CMEK-Enforced Object Lakehouse)
resource "google_storage_bucket" "raw_lakehouse" {
  name                        = "bkt-raw-lakehouse-${var.environment}-${random_id.bucket_suffix.hex}"
  location                    = var.region
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  versioning {
    enabled = true
  }

  encryption {
    default_kms_key_name = google_kms_crypto_key.ck_gcs_lakehouse.id
  }

  lifecycle_rule {
    condition {
      age = 30
    }
    action {
      type          = "SetStorageClass"
      storage_class = "NEARLINE"
    }
  }

  lifecycle_rule {
    condition {
      age = 90
    }
    action {
      type          = "SetStorageClass"
      storage_class = "COLDLINE"
    }
  }

  lifecycle_rule {
    condition {
      age = 365
    }
    action {
      type          = "SetStorageClass"
      storage_class = "ARCHIVE"
    }
  }

  depends_on = [google_kms_crypto_key_iam_member.gcs_encrypter_decrypter]
}

resource "google_storage_bucket" "deadletter" {
  name                        = "bkt-deadletter-${var.environment}-${random_id.bucket_suffix.hex}"
  location                    = var.region
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  encryption {
    default_kms_key_name = google_kms_crypto_key.ck_gcs_lakehouse.id
  }

  depends_on = [google_kms_crypto_key_iam_member.gcs_encrypter_decrypter]
}

resource "google_storage_bucket" "dataflow_staging" {
  name                        = "bkt-dataflow-staging-${var.environment}-${random_id.bucket_suffix.hex}"
  location                    = var.region
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  encryption {
    default_kms_key_name = google_kms_crypto_key.ck_gcs_lakehouse.id
  }

  depends_on = [google_kms_crypto_key_iam_member.gcs_encrypter_decrypter]
}

# Fine-grained Bucket IAM
resource "google_storage_bucket_iam_member" "lake_writer_creator" {
  bucket = google_storage_bucket.raw_lakehouse.name
  role   = "roles/storage.objectCreator"
  member = "serviceAccount:${google_service_account.sa_lake_writer.email}"
}

resource "google_storage_bucket_iam_member" "lake_writer_viewer" {
  bucket = google_storage_bucket.raw_lakehouse.name
  role   = "roles/storage.objectViewer"
