  name         = "events.telemetry.dlq"
  kms_key_name = google_kms_crypto_key.ck_pubsub_ingest.id

  message_retention_duration = "604800s" # 7 days

  depends_on = [google_kms_crypto_key_iam_member.pubsub_encrypter_decrypter]
}

resource "google_pubsub_topic" "raw_telemetry" {
  name         = "events.telemetry.raw"
  kms_key_name = google_kms_crypto_key.ck_pubsub_ingest.id

  message_retention_duration = "604800s" # 7 days retention

  depends_on = [google_kms_crypto_key_iam_member.pubsub_encrypter_decrypter]
}

resource "google_pubsub_topic_iam_member" "producer_publisher" {
  topic  = google_pubsub_topic.raw_telemetry.name
  role   = "roles/pubsub.publisher"
  member = "serviceAccount:${google_service_account.sa_event_producer.email}"
}

# Pull Subscription for Streaming Engine (Dataflow)
resource "google_pubsub_subscription" "dataflow_sub" {
  name  = "sub-telemetry-dataflow"
  topic = google_pubsub_topic.raw_telemetry.name

  ack_deadline_seconds       = 60
  retain_acked_messages      = false
  message_retention_duration = "604800s"

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.deadletter_telemetry.id
    max_delivery_attempts = 5
  }

  retry_policy {
    minimum_backoff = "10s"
    maximum_backoff = "600s"
  }
}

# Direct-to-BigQuery Subscription
resource "google_pubsub_subscription" "bq_direct_sub" {
  name  = "sub-telemetry-bigquery-direct"
  topic = google_pubsub_topic.raw_telemetry.name

  bigquery_config {
    table            = "${var.project_id}:${google_bigquery_table.telemetry_staging.dataset_id}.${google_bigquery_table.telemetry_staging.table_id}"
    use_topic_schema = false
    write_metadata   = true
  }

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.deadletter_telemetry.id
    max_delivery_attempts = 5
  }

  depends_on = [
    google_bigquery_dataset_iam_member.bq_direct_writer_editor,
    google_bigquery_dataset_iam_member.bq_direct_writer_viewer
  ]
}

# 4. Management & Operational Bastion Host
resource "google_compute_instance" "bastion_host" {
  name         = "vm-analytics-mgmt-bastion"
  machine_type = "e2-medium"
  zone         = "${var.region}-a"

  tags = ["bastion-host"]

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      size  = 30
      type  = "pd-standard"
    }
    kms_key_self_link = google_kms_crypto_key.ck_dataflow_worker_pd.id
  }

  network_interface {
    subnetwork = google_compute_subnetwork.sb_mgmt_bastion.id
    # No public external IP configured; strictly accessed via Identity-Aware Proxy (IAP)
  }

  service_account {
    email  = google_service_account.sa_bastion_admin.email
    scopes = ["cloud-platform"]
  }

  metadata = {
    enable-oslogin = "TRUE"
  }

  shielded_instance_config {
    enable_secure_boot          = true
    enable_vtpm                 = true
    enable_integrity_monitoring = true
  }

  depends_on = [google_kms_crypto_key_iam_member.compute_encrypter_decrypter]
}
```

