### File: `network.tf`

```hcl
# 1. Custom VPC Network
resource "google_compute_network" "vpc" {
  name                            = var.network_name
  auto_create_subnetworks         = false
  routing_mode                    = "REGIONAL"
  mtu                             = 1460
  delete_default_routes_on_create = true
  depends_on                      = [google_project_service.apis]
}

# 2. Subnets
resource "google_compute_subnetwork" "sb_dataflow" {
  name                     = "sb-${var.region}-dataflow"
  ip_cidr_range            = var.subnet_cidr_dataflow
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_10_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}

resource "google_compute_subnetwork" "sb_ingest_proxy" {
  name                     = "sb-${var.region}-ingest-proxy"
  ip_cidr_range            = var.subnet_cidr_ingest_proxy
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "gke-pods-range"
    ip_cidr_range = var.gke_pods_cidr
  }

  secondary_ip_range {
    range_name    = "gke-services-range"
    ip_cidr_range = var.gke_services_cidr
  }

  log_config {
    aggregation_interval = "INTERVAL_10_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}

resource "google_compute_subnetwork" "sb_psc_endpoints" {
  name                     = "sb-${var.region}-psc-endpoints"
  ip_cidr_range            = var.subnet_cidr_psc_endpoints
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = false
}

resource "google_compute_subnetwork" "sb_proxy_only" {
  name          = "sb-${var.region}-proxy-only"
  ip_cidr_range = var.subnet_cidr_proxy_only
  region        = var.region
  network       = google_compute_network.vpc.id
  purpose       = "REGIONAL_MANAGED_PROXY"
  role          = "ACTIVE"
}

resource "google_compute_subnetwork" "sb_mgmt_bastion" {
  name                     = "sb-${var.region}-mgmt-bastion"
  ip_cidr_range            = var.subnet_cidr_mgmt_bastion
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_10_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}

# 3. Cloud Router & High-Throughput Cloud NAT
resource "google_compute_router" "router" {
  name    = "cr-analytics-${var.region}"
  region  = var.region
  network = google_compute_network.vpc.id

  bgp {
    asn = 64514
  }
}

resource "google_compute_address" "nat_ips" {
  count  = 2
  name   = "pip-nat-${var.region}-0${count.index + 1}"
  region = var.region
}

resource "google_compute_router_nat" "nat" {
  name                               = "nat-gw-${var.region}"
  router                             = google_compute_router.router.name
  region                             = var.region
  nat_ip_allocate_option             = "MANUAL_ONLY"
  nat_ips                            = google_compute_address.nat_ips[*].self_link
  source_subnetwork_ip_ranges_to_nat = "LIST_OF_SUBNETWORKS"

  subnetwork {
    name                    = google_compute_subnetwork.sb_dataflow.id
    source_ip_ranges_to_nat = ["ALL_IP_RANGES"]
  }

  subnetwork {
    name                    = google_compute_subnetwork.sb_ingest_proxy.id
    source_ip_ranges_to_nat = ["ALL_IP_RANGES"]
  }

  min_ports_per_vm                 = 256
  max_ports_per_vm                 = 4096
  enable_dynamic_port_allocation   = true
  tcp_established_idle_timeout_sec = 1200
  tcp_transitory_idle_timeout_sec  = 30
  udp_idle_timeout_sec             = 30

  log_config {
    enable = true
    filter = "ERRORS_ONLY"
  }
}

# 4. Zero-Trust Stateful VPC Firewall Rules

# Baseline Denials
resource "google_compute_firewall" "fw_e_deny_all" {
  name               = "fw-e-deny-all"
  network            = google_compute_network.vpc.name
  direction          = "EGRESS"
  priority           = 65534
  destination_ranges = ["0.0.0.0/0"]

  deny {
    protocol = "all"
  }

  log_config {
    metadata = "INCLUDE_ALL_METADATA"
  }
}

resource "google_compute_firewall" "fw_i_deny_all" {
  name          = "fw-i-deny-all"
  network       = google_compute_network.vpc.name
  direction     = "INGRESS"
  priority      = 65534
  source_ranges = ["0.0.0.0/0"]

  deny {
    protocol = "all"
  }

  log_config {
    metadata = "INCLUDE_ALL_METADATA"
  }
}

# Allow Dataflow Inter-Worker IPC
resource "google_compute_firewall" "fw_i_allow_dataflow_worker_ipc" {
  name               = "fw-i-allow-dataflow-worker-ipc"
  network            = google_compute_network.vpc.name
  direction          = "INGRESS"
  priority           = 100
  source_ranges      = [var.subnet_cidr_dataflow]
  destination_ranges = [var.subnet_cidr_dataflow]
  target_service_accounts = [
    google_service_account.sa_dataflow_worker.email
  ]

  allow {
    protocol = "tcp"
    ports    = ["12345", "12346"]
  }
}

resource "google_compute_firewall" "fw_e_allow_dataflow_worker_ipc" {
  name               = "fw-e-allow-dataflow-worker-ipc"
  network            = google_compute_network.vpc.name
  direction          = "EGRESS"
  priority           = 120
  destination_ranges = [var.subnet_cidr_dataflow]
  target_service_accounts = [
    google_service_account.sa_dataflow_worker.email
  ]

  allow {
    protocol = "tcp"
    ports    = ["12345", "12346"]
  }
}

# Allow Google Cloud Health Probes
resource "google_compute_firewall" "fw_i_allow_gcp_health_checks" {
  name          = "fw-i-allow-gcp-health-checks"
  network       = google_compute_network.vpc.name
  direction     = "INGRESS"
  priority      = 110
  source_ranges = ["35.191.0.0/16", "130.211.0.0/22"]
  target_tags   = ["load-balanced-backend"]

  allow {
    protocol = "tcp"
    ports    = ["443", "8080", "8443"]
  }
}

# Allow IAP Tunneling for Bastion Access
resource "google_compute_firewall" "fw_i_allow_iap_admin_ssh" {
  name               = "fw-i-allow-iap-admin-ssh"
  network            = google_compute_network.vpc.name
  direction          = "INGRESS"
  priority           = 120
  source_ranges      = ["35.235.240.0/20"]
  destination_ranges = [var.subnet_cidr_mgmt_bastion]
  target_tags        = ["bastion-host"]

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }
}

# Allow Proxy Subnet to API Backends
resource "google_compute_firewall" "fw_i_allow_proxy_to_backends" {
  name               = "fw-i-allow-proxy-to-backends"
  network            = google_compute_network.vpc.name
  direction          = "INGRESS"
  priority           = 130
  source_ranges      = [var.subnet_cidr_proxy_only]
  destination_ranges = [var.subnet_cidr_ingest_proxy]
  target_tags        = ["ingest-api"]

  allow {
    protocol = "tcp"
    ports    = ["8080", "8443"]
  }
}

# Allow Egress to PSC VIP for Google APIs
resource "google_compute_firewall" "fw_e_allow_psc_google_apis" {
  name               = "fw-e-allow-psc-google-apis"
  network            = google_compute_network.vpc.name
  direction          = "EGRESS"
  priority           = 100
  destination_ranges = ["${var.psc_google_apis_address}/32"]

  allow {
    protocol = "tcp"
    ports    = ["443"]
  }
}

# Allow Fallback Egress to Private/Restricted Google API ranges
resource "google_compute_firewall" "fw_e_allow_pga_google_ranges" {
  name               = "fw-e-allow-pga-google-ranges"
  network            = google_compute_network.vpc.name
  direction          = "EGRESS"
  priority           = 110
  destination_ranges = ["199.36.153.8/30", "199.36.153.4/30"]

  allow {
    protocol = "tcp"
    ports    = ["443"]
  }
}

# Allow Controlled Egress to NAT Gateway
resource "google_compute_firewall" "fw_e_allow_nat_egress" {
  name               = "fw-e-allow-nat-egress"
  network            = google_compute_network.vpc.name
  direction          = "EGRESS"
  priority           = 130
  destination_ranges = ["0.0.0.0/0"]
  target_tags        = ["nat-egress-enabled"]

  allow {
    protocol = "tcp"
    ports    = ["80", "443"]
  }
}

# Allow Internal DNS queries
resource "google_compute_firewall" "fw_e_allow_internal_dns" {
  name               = "fw-e-allow-internal-dns"
  network            = google_compute_network.vpc.name
  direction          = "EGRESS"
  priority           = 140
  destination_ranges = ["169.254.169.254/32", "10.100.0.0/18"]

  allow {
    protocol = "tcp"
    ports    = ["53"]
  }
  allow {
    protocol = "udp"
    ports    = ["53"]
  }
}

# 5. Private Service Connect (PSC) for Google APIs
resource "google_compute_global_address" "psc_google_apis" {
  name         = "ga-psc-google-apis"
  address_type = "INTERNAL"
  purpose      = "PRIVATE_SERVICE_CONNECT"
  network      = google_compute_network.vpc.id
  address      = var.psc_google_apis_address
}

resource "google_compute_global_forwarding_rule" "psc_google_apis" {
  name                  = "fwd-rule-psc-google-apis"
  target                = "all-apis"
  network               = google_compute_network.vpc.id
  ip_address            = google_compute_global_address.psc_google_apis.id
  load_balancing_scheme = ""
}

# 6. Private DNS Strategy for API Redirection
resource "google_dns_managed_zone" "googleapis" {
  name        = "pz-google-apis-override"
  dns_name    = "googleapis.com."
  description = "Private DNS zone intercepting and directing googleapis.com to local PSC Endpoint VIP."
  visibility  = "private"

  private_visibility_config {
    networks {
      network_url = google_compute_network.vpc.id
    }
  }

  depends_on = [google_project_service.apis]
}

resource "google_dns_record_set" "psc_endpoint_a" {
  name         = "psc-endpoint.googleapis.com."
  type         = "A"
  ttl          = 300
  managed_zone = google_dns_managed_zone.googleapis.name
  rrdatas      = [var.psc_google_apis_address]
}

resource "google_dns_record_set" "googleapis_cname" {
  name         = "*.googleapis.com."
  type         = "CNAME"
  ttl          = 300
  managed_zone = google_dns_managed_zone.googleapis.name
  rrdatas      = ["psc-endpoint.googleapis.com."]
}
```

