### File: `security.tf`

```hcl
data "google_project" "current" {
  project_id = var.project_id
}

# 1. Customer-Managed Encryption Keys (CMEK) via Cloud KMS

# Key Rings partitioned by service domain
resource "google_kms_key_ring" "kr_pubsub" {
  name       = "kr-analytics-pubsub"
  location   = var.region
  depends_on = [google_project_service.apis]
}

resource "google_kms_key_ring" "kr_gcs" {
  name       = "kr-analytics-gcs"
  location   = var.region
  depends_on = [google_project_service.apis]
}

resource "google_kms_key_ring" "kr_bigquery" {
  name       = "kr-analytics-bigquery"
  location   = var.region
  depends_on = [google_project_service.apis]
}

resource "google_kms_key_ring" "kr_compute" {
  name       = "kr-analytics-compute"
  location   = var.region
  depends_on = [google_project_service.apis]
}

# Symmetric CryptoKeys with automated 90-day rotation
resource "google_kms_crypto_key" "ck_pubsub_ingest" {
  name            = "ck-pubsub-ingest"
  key_ring        = google_kms_key_ring.kr_pubsub.id
  rotation_period = var.key_rotation_period

  version_template {
    algorithm        = "GOOGLE_SYMMETRIC_ENCRYPTION"
    protection_level = "HSM"
  }
}

resource "google_kms_crypto_key" "ck_gcs_lakehouse" {
  name            = "ck-gcs-lakehouse"
  key_ring        = google_kms_key_ring.kr_gcs.id
  rotation_period = var.key_rotation_period

  version_template {
    algorithm        = "GOOGLE_SYMMETRIC_ENCRYPTION"
    protection_level = "HSM"
  }
}

resource "google_kms_crypto_key" "ck_bigquery_analytics" {
  name            = "ck-bigquery-analytics"
  key_ring        = google_kms_key_ring.kr_bigquery.id
  rotation_period = var.key_rotation_period

  version_template {
    algorithm        = "GOOGLE_SYMMETRIC_ENCRYPTION"
    protection_level = "HSM"
  }
}

resource "google_kms_crypto_key" "ck_dataflow_worker_pd" {
  name            = "ck-dataflow-worker-pd"
  key_ring        = google_kms_key_ring.kr_compute.id
  rotation_period = var.key_rotation_period

  version_template {
    algorithm        = "GOOGLE_SYMMETRIC_ENCRYPTION"
    protection_level = "HSM"
  }
}

# 2. Google Managed Service Identities (Service Agents)
resource "google_project_service_identity" "pubsub_agent" {
  provider = google-beta
  project  = var.project_id
  service  = "pubsub.googleapis.com"
}

resource "google_project_service_identity" "storage_agent" {
  provider = google-beta
  project  = var.project_id
  service  = "storage.googleapis.com"
}

resource "google_project_service_identity" "bigquery_agent" {
  provider = google-beta
  project  = var.project_id
  service  = "bigquery.googleapis.com"
