resource "google_pubsub_topic" "deadletter_telemetry" {
  name         = "events.telemetry.dlq"
  kms_key_name = google_kms_crypto_key.ck_pubsub_ingest.id

  message_retention_duration = "604800s" # 7 days

  depends_on = [google_kms_crypto_key_iam_member.pubsub_encrypter_decrypter]
}

resource "google_pubsub_topic" "raw_telemetry" {
  name         = "events.telemetry.raw"
  kms_key_name = google_kms_crypto_key.ck_pubsub_ingest.id

  message_retention_duration = "604800s" # 7 days retention

  depends_on = [google_kms_crypto_key_iam_member.pubsub_encrypter_decrypter]
}

resource "google_pubsub_topic_iam_member" "producer_publisher" {
